    bronze_bridle_buckle = { name = "Bronasta sponka za uzde", bronzeCost = 4, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 425, prestige = 6, happiness = 3, description = "Bronasta sponka za trdovratne uzde." },
    silver_bridle_buckle = { name = "Srebrna sponka za uzde", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 1025, prestige = 11, happiness = 4, description = "Srebrna sponka za plemiške uzde." },
    gilded_bridle_buckle = { name = "Pozlačena sponka za uzde", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2200, prestige = 20, happiness = 5, description = "Pozlačena sponka za dvorne uzde." },
