    master_bridlebuckle_atelier = { name = "Mojstrski spončni atelje", cost = { gold = 3100, wood = 420, stone = 530, silver = 36, gold = 7 }, upkeep = 73, qualityBonus = 30 },
    sovereign_bridlebuckle_palace = { name = "Suverena spončna palača", cost = { gold = 13200, wood = 650, stone = 840, gold = 85, jewel = 19 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
BridleBuckleMaker.ironStock = 16; BridleBuckleMaker.bronzeStock = 14; BridleBuckleMaker.woodStock = 10; BridleBuckleMaker.leatherStock = 10; BridleBuckleMaker.silverStock = 8; BridleBuckleMaker.goldStock = 6; BridleBuckleMaker.jewelStock = 4; BridleBuckleMaker.pearlStock = 4
BridleBuckleMaker.productStock = {}; BridleBuckleMaker.buildings = {}; BridleBuckleMaker.maker = nil; BridleBuckleMaker.activeMaking = {}; BridleBuckleMaker.totalProducts = 0; BridleBuckleMaker.dayTimer = 0
function BridleBuckleMaker.init() BridleBuckleMaker.ironStock=16; BridleBuckleMaker.bronzeStock=14; BridleBuckleMaker.woodStock=10; BridleBuckleMaker.leatherStock=10; BridleBuckleMaker.silverStock=8; BridleBuckleMaker.goldStock=6; BridleBuckleMaker.jewelStock=4; BridleBuckleMaker.pearlStock=4; BridleBuckleMaker.productStock={}; BridleBuckleMaker.buildings={}; BridleBuckleMaker.maker=nil; BridleBuckleMaker.activeMaking={}; BridleBuckleMaker.totalProducts=0; BridleBuckleMaker.dayTimer=0; print("[BridleBuckleMaker] Royal Bridle Buckle Maker System initialized (6 products, 4 buildings)") end
function BridleBuckleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BridleBuckleMaker.maker={name=n or ("Sponkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sponkar najet: %s (spretnost: %d)",BridleBuckleMaker.maker.name,s),"success") end; return true end
function BridleBuckleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BridleBuckleMaker.build(id) local ok,e=BridleBuckleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BridleBuckleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BridleBuckleMaker.getQualityBonus() local b=0; for _,bd in ipairs(BridleBuckleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BridleBuckleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BridleBuckleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BridleBuckleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BridleBuckleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BridleBuckleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BridleBuckleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BridleBuckleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BridleBuckleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BridleBuckleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BridleBuckleMaker.buildings==0 then return false,"Potrebna spončna delavnica" end; if not BridleBuckleMaker.maker then return false,"Potreben sponkar" end; return true end
function BridleBuckleMaker.make(pt,qty) qty=qty or 1; local ok,e=BridleBuckleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BridleBuckleMaker.ironStock=BridleBuckleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BridleBuckleMaker.bronzeStock=BridleBuckleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BridleBuckleMaker.woodStock=BridleBuckleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BridleBuckleMaker.leatherStock=BridleBuckleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BridleBuckleMaker.silverStock=BridleBuckleMaker.silverStock-d.silverCost*qty end; if d.goldCost then BridleBuckleMaker.goldStock=BridleBuckleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BridleBuckleMaker.jewelStock=BridleBuckleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BridleBuckleMaker.pearlStock=BridleBuckleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BridleBuckleMaker.maker then t=math.max(1,t-math.floor(BridleBuckleMaker.maker.skill/13)) end; table.insert(BridleBuckleMaker.activeMaking,{id="bridlebuckle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BridleBuckleMaker.completeMaking(m) local q=1.0+(BridleBuckleMaker.getQualityBonus()/100); if BridleBuckleMaker.maker then q=q+(BridleBuckleMaker.maker.skill/140) end; q=math.min(2.5,q); BridleBuckleMaker.productStock[m.productType]=(BridleBuckleMaker.productStock[m.productType] or 0)+m.quantity; BridleBuckleMaker.totalProducts=BridleBuckleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BridleBuckleMaker.maker then BridleBuckleMaker.maker.itemsMade=BridleBuckleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BridleBuckleMaker.maker.skill=math.min(100,BridleBuckleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sponka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bridlebuckle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BridleBuckleMaker.update(dt) if not _G.state then return end; BridleBuckleMaker.dayTimer=BridleBuckleMaker.dayTimer+dt; if BridleBuckleMaker.dayTimer>=30 then BridleBuckleMaker.dayTimer=0; for i=#BridleBuckleMaker.activeMaking,1,-1 do local m=BridleBuckleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BridleBuckleMaker.completeMaking(m); table.remove(BridleBuckleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BridleBuckleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BridleBuckleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BridleBuckleMaker.getStats() return {ironStock=BridleBuckleMaker.ironStock,bronzeStock=BridleBuckleMaker.bronzeStock,woodStock=BridleBuckleMaker.woodStock,leatherStock=BridleBuckleMaker.leatherStock,silverStock=BridleBuckleMaker.silverStock,goldStock=BridleBuckleMaker.goldStock,jewelStock=BridleBuckleMaker.jewelStock,pearlStock=BridleBuckleMaker.pearlStock,productStock=BridleBuckleMaker.productStock,numBuildings=#BridleBuckleMaker.buildings,hasMaker=BridleBuckleMaker.maker~=nil,makerName=BridleBuckleMaker.maker and BridleBuckleMaker.maker.name or "—",makerSkill=BridleBuckleMaker.maker and BridleBuckleMaker.maker.skill or 0,activeMaking=#BridleBuckleMaker.activeMaking,totalProducts=BridleBuckleMaker.totalProducts} end
return BridleBuckleMaker
